SET NAMES utf8mb4;
USE animal_db;
UPDATE animal SET name='莉莉', category='DOG', sex='FEMALE', body_size='MEDIUM', age=11, avatar='https://www.pohome.cn/upload/img/pet/avatar/large/175746080483313953.jpeg', is_sterilized=1, activity_scope='北京', status=1, description='莉莉性格胆小谨慎，需要比较长的时间和耐心来磨合。已免疫、已绝育。', detail_content='<p>流浪狗在城市里的生存空间非常有限，自己流浪，翻翻垃圾桶还能找点东西吃，但生了小baby的狗狗想要活下去就更难了。莉莉就是这样一个流浪狗妈妈，它本性格温顺安静，被遗弃在北京昌平区的一个小区里，自从生了一窝小狗，就开始了日复一日地遭人厉喝驱赶的日子。莉莉为了保护自己的孩子，变得不再温顺，在艰难的寻找安全落脚点的过程中，3个孩子只剩下了1个。狗妈莉莉每天顽强地对抗着全世界，直到被志愿者救起，莉莉一直处于戒备状态。</p><figure class="image"><img src="https://www.pohome.cn/upload/img/blog/content/175746067329452320.png"></figure><p>被救助后的生活逐渐稳定下来，再加上孩子的陪伴，莉莉开始慢慢地重新和人类建立感情，越来越亲人，越来越多互动。但是对于想要领养莉莉的家庭，我们有个小小的私心，希望莉莉能和它的孩子“淘淘”一起被领养，让它和孩子不再分离。</p>' WHERE id=29;
UPDATE animal SET name='警长', category='CAT', sex='MALE', body_size='SMALL', age=7, avatar='https://www.pohome.cn/upload/img/pet/avatar/large/175746027657365791.jpeg', is_sterilized=1, activity_scope='北京', status=1, description='警长身材苗条匀称，活力四射，已免疫、已绝育。', detail_content='<p>捡猫奇遇记</p><p>救助小警长纯属意外，可以说是小警长在主动自救。</p><figure class="image"><img src="https://www.pohome.cn/upload/img/blog/content/175746012948990238.png"></figure><p>2019年冬天，救助人本是去北京天通苑的一家物美超市买菜的，买完菜一出超市大门口，就被不明物体冲过来一把抱住了大腿，然后就顺着裤腿往身上爬。讲真，救助人当时还真是被吓了一大跳。低头一看，原来是只2个月左右的小猫咪，喵喵叫着抓住救助人的裤子不放手，一副认真求助、一定要让人把它带回家的模样，恐怕这就是传说中的“被猫选中了”。救助人只好一手拎着菜兜子，一手抱着猫回家。</p><p>小警长身材苗条，细胳膊细腿小瘦脸，是北方很少见的体型，像暹罗猫，性格也像，活泼好动，好奇心强，跟熟悉的人非常亲近。</p>' WHERE id=30;
UPDATE animal SET name='翠花', category='CAT', sex='FEMALE', body_size='SMALL', age=10, avatar='https://www.pohome.cn/upload/img/pet/avatar/large/175745987330181405.jpeg', is_sterilized=1, activity_scope='北京', status=1, description='翠花的左耳发生了耳血肿，反复做了2次手术，手术后的翠花变成了人工合成“折耳猫”，已免疫、已绝育。', detail_content='<p>翠花，是个漂亮的三花猫，也可以被称为“花臂大佬”。2016年春，汪喵志愿者在北京顺义樱花园小区进行的流浪猫TNR（抓捕-绝育-放归）项目时，遇见了半岁大的翠花。虽然它是个流浪二代，但它表现得非常亲人，送到医院做完绝育之后，又进行了体检、驱虫和免疫，留在猫屋准备找领养试试看。</p><figure class="image"><img src="https://www.pohome.cn/upload/img/blog/content/175745980802533660.png"></figure><p>去年，翠花的左耳发生了耳血肿，反复做了2次手术，手术后的翠花变成了人工合成“折耳猫”。</p><p>翠花跟其它猫咪相处融洽，好奇心非常强，爱探索新世界，喜欢吃罐头和肉肉，不喜欢被抱，与人为善但不是很粘人那一款哦。</p>' WHERE id=31;
UPDATE animal SET name='大白', category='CAT', sex='MALE', body_size='SMALL', age=19, avatar='https://www.pohome.cn/upload/img/pet/avatar/large/175745508647635222.jpeg', is_sterilized=1, activity_scope='北京', status=1, description='大白是猫屋里的老住户，一双迷人的浅蓝色眼睛，一身雪白的大长毛，与世无争。已免疫、已绝育。', detail_content='<p>大白是猫屋里的老住户了，一双迷人的浅蓝色眼睛，一身雪白的大长毛，想当年可以说是老北京人的最爱！</p><figure class="image"><img src="https://www.pohome.cn/upload/img/blog/content/175745494700263701.png"></figure><p>2013年，大白的原主人全家南迁，原主人把家里养的4只大猫一起遗弃了。长期在室内生活的家猫根本没有户外生存能力，突然的环境改变和无处觅食导致其中两只猫急性肾衰，后来都回喵星了。大白和弟弟小多跟着志愿者去了医院，左后腿因为血液病问题导致脚趾坏死，手术摘除了一个脚趾头，输液20多天后顺利出院，开始了集体生活。</p><p>大白很爱护弟弟小多，在猫屋这种多猫环境里，难免会有喵星人互相看着不顺眼而闹矛盾。每次小多被其它猫欺负了，大白都会马上冲过去帮忙，当然最后很可能是兄弟俩一起被打，还要铲屎官来调解维和。</p><p>大白性格温和亲人，老成稳定，每天吃喝完毕就晒太阳睡觉，可乖了。</p>' WHERE id=32;
UPDATE animal SET name='巴豆', category='DOG', sex='MALE', body_size='MEDIUM', age=9, avatar='https://www.pohome.cn/upload/img/pet/avatar/large/175653768091142236.jpeg', is_sterilized=1, activity_scope='北京', status=1, description='巴豆已免疫、已绝育，性格亲人活泼，右前腿曾受伤坏死，但完全不影响正常生活。', detail_content='<p>我们与巴豆的第一次见面是在2016年秋天，它只有3个月大，还是个毛绒绒的小朋友，坐在垃圾桶旁边哼哼唧唧地哭着，右前腿有血迹，伤口已经结痂，志愿者目测被车撞伤的可能性很大，送到医院进行检查后医生的诊断是：右前腿坏死，终身残疾。</p><p>在医院完成了全套的治疗、驱虫、免疫和绝育后，小巴豆开始了集体生活。一晃5年过去了，巴豆长成一个大姑娘，没有所谓高贵的血统、迷你的体型，只是个普普通通的中华田园犬，但巴豆有温顺的性格和好身体。它已经习惯了右前腿的小问题，可以正常地走路和跑跳，一点都不碍事。将来巴豆的领养人只要每年定期带它去医院做个小体检就可以了，其实照顾一只略有残疾的狗狗也并不是什么费劲的事，反而更有意义，不是吗？</p><figure class="image"><img src="https://www.pohome.cn/upload/img/blog/content/175653743840987227.png"></figure>' WHERE id=33;
